/**
 * The browser-side half of the fixture-source guard.
 *
 * Generation and rendering are different machines. The node guard proves the
 * corpus on disk was genuine; this proves what reached the browser still is.
 * Absent data looks exactly like the empty state, so this must be a POSITIVE
 * assertion on authored content, never a count.
 */
export function assertCorpusIsGenuine(): void {
  const fail = (why: string): never => {
    throw new Error('PEMO FIXTURE SOURCE GUARD (browser) FAILED — ' + why);
  };
  const s1 = CORPUS['mob-s1-safety/default.json'] as any;
  const smoke = s1?.events?.find((e: any) => e?.reference === 'HS-2026-08-12-004417');
  if (!smoke) fail('the authored event HS-2026-08-12-004417 is absent');
  if (smoke.title?.['zh-Hant'] !== '單位偵測到煙霧') fail('the Traditional Chinese title is absent');
  const s2 = CORPUS['mob-s2-overview/default.json'] as any;
  const hub = s2?.integrationHealth?.find((f: any) => f?.key === 'twoiothub');
  if (hub?.name !== '2IoThub') fail('the 2IoThub feed name is wrong or absent');
  const s5cycle = CORPUS['mob-s5-notices/lifecycle.json'] as any;
  const stuck = s5cycle?.notices?.find((n: any) => n?.lifecycleState === 'pending_approval');
  if (!stuck) fail('the notice stuck at pending_approval is absent');
  const s5 = CORPUS['mob-s5-notices/detail.json'] as any;
  const granted = s5?.notice?.history?.some((h: any) => h?.disposition === 'approval_granted');
  if (!granted) fail('the approval_granted disposition is absent from the history chain');
  if (CORPUS_SURFACE !== 'management') fail('this is not the management corpus');
}
